import {supabase,currentUser} from './auth-client.mjs';
import {isCommunityPreview,validateCommunityEntry,publicCommunityEntries} from './community-model.mjs';
export const communityPreview=isCommunityPreview();export const COMMUNITY_STORAGE='tatari-community-preview-v1';const root=new URL('.',import.meta.url);let defaults;
async function seeds(){return defaults??=fetch(new URL('./community-defaults.json',root)).then(r=>{if(!r.ok)throw Error('Creator data could not load.');return r.json()});}
async function localRows(){const raw=localStorage.getItem(COMMUNITY_STORAGE);if(!raw)return structuredClone(await seeds());let rows;try{rows=JSON.parse(raw)}catch{throw Error('The local preview data could not be read.');}if(!Array.isArray(rows))throw Error('Invalid local preview data.');for(const seed of await seeds())if(['code','patch'].includes(seed.kind)&&!rows.some(row=>row.id===seed.id))rows.push(structuredClone(seed));for(const row of rows)if(row.id==='95bc3aa5-8fef-4644-a746-a95121fd0930')for(const key of ['draft','published'])if(row[key]&&row[key].creator_code===undefined)row[key].creator_code='ARTIARYT';return rows;}
export async function communityPublic(){const draftId=new URL(location.href).searchParams.get('draft');if(draftId&&!communityPreview){const row=await communityAdmin('get',{id:draftId});return publicCommunityEntries([row],{draftId});}if(communityPreview)return publicCommunityEntries(await localRows(),{draftId:new URL(location.href).searchParams.get('draft')||''});const {data,error}=await supabase.rpc('public_community_entries');if(error?.code==='PGRST202')return publicCommunityEntries(await seeds());if(error)throw Error('Community updates are unavailable. Please try again later.');return data;}
export async function communityAdmin(action,payload={}){if(communityPreview){const rows=await localRows();if(action==='list')return rows.map(row=>({...row,draft:validateCommunityEntry(row.kind,row.draft)}));let entry=rows.find(r=>r.id===payload.id);if(action==='history'){if(!entry)throw Error('This entry no longer exists.');return localHistory(entry);}if(action==='get'){if(!entry)throw Error('This entry no longer exists.');return structuredClone(entry);}if(entry)localHistory(entry);if(action==='create'){entry={id:crypto.randomUUID(),kind:payload.kind,revision:0,draft:validateCommunityEntry(payload.kind,payload.content),published:null,published_at:null};rows.unshift(entry);}else{if(!entry)throw Error('This entry no longer exists.');if(entry.revision!==payload.revision)throw Error('This entry changed in another tab. Reload it before saving.');if(action==='save')entry.draft=validateCommunityEntry(entry.kind,payload.content);else if(action==='publish'){entry.published=validateCommunityEntry(entry.kind,entry.draft,{publish:true});entry.published_at=new Date().toISOString();}else if(action==='unpublish'){entry.published=null;entry.published_at=null;}else if(action==='restore'){const version=localHistory(entry).find(v=>String(v.id)===String(payload.version));if(!version)throw Error('This version does not belong to this entry.');entry.draft=validateCommunityEntry(entry.kind,version.snapshot.draft);}else throw Error('Unknown community action.');entry.revision++;}recordLocalVersion(entry,action);localStorage.setItem(COMMUNITY_STORAGE,JSON.stringify(rows));window.dispatchEvent(new Event('community-preview-changed'));return structuredClone(entry);}
const actor=await currentUser();if(!actor)throw Error('Sign in with your administrator account.');const {data,error}=action==='restore'?await supabase.rpc('community_restore_draft',{p_id:payload.id,p_version:payload.version,p_revision:payload.revision,p_expected_actor:actor.id}):await supabase.rpc('community_workspace',{p_action:action,p_payload:{...payload,expected_actor:actor.id}});if(error)throw Error(error.code==='PGRST202'?'Community publishing needs the prepared database migration.':error.message);if((await currentUser())?.id!==actor.id)throw Error('Your account changed. Reload the dashboard.');return data;}

const VOTES_STORAGE='tatari-community-votes-preview-v1';
function localVotes(){try{return JSON.parse(localStorage.getItem(VOTES_STORAGE)||'{}')}catch{return {}}}
export async function communityVotes(){if(communityPreview){const votes=localVotes();return Object.entries(votes).map(([id,mine])=>({id,likes:mine===1?1:0,dislikes:mine===-1?1:0,mine}));}const {data,error}=await supabase.rpc('community_code_votes');if(error?.code==='PGRST202')throw Error('Live voting is pending database setup.');if(error)throw Error('Code votes could not load.');return data;}
export async function voteCommunityCode(id,vote){if(![-1,0,1].includes(vote))throw Error('Invalid vote.');if(communityPreview){const rows=await localRows();if(!rows.some(r=>r.id===id&&r.kind==='code'&&r.published))throw Error('This code is no longer published.');const votes=localVotes();votes[id]=vote;localStorage.setItem(VOTES_STORAGE,JSON.stringify(votes));return;}const actor=await currentUser();if(!actor)throw Error('Sign in to vote on a code.');const {error}=await supabase.rpc('vote_community_code',{p_id:id,p_vote:vote,p_actor:actor.id});if(error)throw Error(error.code==='PGRST202'?'Live voting is pending database setup.':error.message);}

function historyKey(id){return 'community-history-preview-v1:'+id;}
function localHistory(entry){let list;try{list=JSON.parse(localStorage.getItem(historyKey(entry.id))||'null');}catch{}if(!Array.isArray(list)){list=[{id:1,action:'original',snapshot:structuredClone(entry),created_at:new Date().toISOString()}];localStorage.setItem(historyKey(entry.id),JSON.stringify(list));}return list;}
function recordLocalVersion(entry,action){const list=localHistory(entry);list.unshift({id:Math.max(...list.map(v=>v.id))+1,action,snapshot:structuredClone(entry),created_at:new Date().toISOString()});localStorage.setItem(historyKey(entry.id),JSON.stringify(list));}
